  function icon(type,reward){if(type==="POKESTOP"&&reward?.regular){const radius=stopDotRadius(),size=radius*2;return L.divIcon({className:"",html:`<div class="regular-quest-icon${reward.completed?" completed":""}" style="width:${size}px;height:${size}px">${reward.conflict?'<span class="reward-conflict">!</span>':""}</div>`,iconSize:[size,size],iconAnchor:[radius,radius],popupAnchor:[0,-radius-2]})}if(type==="POKESTOP"&&reward?.image){const taskBadge=reward.taskIcon?`<span class="task-kind-badge" title="${escape(reward.taskKind)} task"><img src="${escape(reward.taskIcon)}" alt="${escape(reward.taskKind)} task"></span>`:reward.taskEmoji?`<span class="task-kind-badge" title="${escape(reward.taskKind)} task" aria-label="${escape(reward.taskKind)} task">${escape(reward.taskEmoji)}</span>`:"",scale=Math.max(.75,Math.min(1,.75+(map.getZoom()-15)/12));return L.divIcon({className:"",html:`<div class="reward-icon reward-${escape(slug(reward.label))}${reward.completed?" completed":""}" style="transform:scale(${scale.toFixed(3)})"><img src="${escape(reward.image)}" alt="${escape(reward.label)}" loading="lazy" decoding="async">${taskBadge}${reward.conflict?'<span class="reward-conflict">!</span>':""}${reward.completed?'<span class="reward-completed" title="Completed locally">✓</span>':""}</div>`,iconSize:[50,50],iconAnchor:[25,25],popupAnchor:[0,-27]})}const key=type==="GYM"?"gym":"stop";return L.divIcon({className:"",html:`<div class="poi-icon ${key}"><span>${type==="GYM"?"★":"●"}</span></div>`,iconSize:[29,29],iconAnchor:[14,28]})}
  function directions(lat,lng){return `https://www.google.com/maps/dir/?api=1&destination=${encodeURIComponent(lat+","+lng)}`}
  function directionsAction(p){return`<a class="icon-action" href="${directions(p.latitude,p.longitude)}" target="_blank" rel="noopener" aria-label="Open directions" title="Open directions"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m3 5 6-3 6 3 6-3v17l-6 3-6-3-6 3V5Zm7-1v13.3l4 2V6.7l-4-2V4Zm-5 2.2v12.6l3-1.5V4.7L5 6.2Zm11 .5v12.6l3-1.5V5.2l-3 1.5Z"/></svg></a>`}
  function hasActiveResearchEvent(){return state.catalogue.some(task=>task.timedEventPriority)}
  function reportsForStop(stopId){const reports=state.reportsByStop.get(stopId)||[];return state.questFilter.active?reports.filter(report=>state.questFilter.selected.has(questKey(report))):reports}
