  function displayedReportsForStop(stopId,rewardQuery=""){const reports=reportsForStop(stopId);if(!rewardQuery)return reports;const matches=reports.filter(report=>rewardName(report.taskId,report.rewardId).toLocaleLowerCase("en").includes(rewardQuery));return matches.length?matches:reports}
  function rewardForStop(stopId,rewardQuery="",excludeRegular=false){const allReports=state.reportsByStop.get(stopId)||[];let reports=displayedReportsForStop(stopId,rewardQuery);if(excludeRegular)reports=reports.filter(report=>!isRegularReport(report));if(!reports.length)return null;const best=[...reports].sort((a,b)=>(b.confirmationCount||0)-(a.confirmationCount||0)||String(b.lastReportedAt||"").localeCompare(String(a.lastReportedAt||"")))[0],completed=isResearchCompleted(stopId,best.taskId,best.rewardId),conflict=allReports.length>1||allReports.some(report=>report.needsReview);if(isRegularReport(best))return{regular:true,label:"Non event quest",completed:false,conflict};const task=state.catalogue.find(item=>item.id===best.taskId),reward=task?.rewards.find(item=>item.id===best.rewardId),kind=taskKindFor(best.taskId);return reward?.image?{image:reward.image,label:reward.label,taskEmoji:kind.emoji,taskIcon:kind.icon,taskKind:kind.label,completed,conflict}:null}
  function researchTooltip(p){const query=$("#search").value.trim().toLocaleLowerCase("en"),rewardQuery=query&&!String(p.name||"").toLocaleLowerCase("en").includes(query)?query:"";let reports=displayedReportsForStop(p.id,rewardQuery);if(map.getZoom()<15)reports=reports.filter(report=>!isRegularReport(report));if(!reports.length)return null;const best=[...reports].sort((a,b)=>(b.confirmationCount||0)-(a.confirmationCount||0)||String(b.lastReportedAt||"").localeCompare(String(a.lastReportedAt||"")))[0];return `<strong>${escape(p.name||"Unnamed PokéStop")}</strong><span>${escape(taskName(best.taskId))}</span>`}
  function addResearchTooltip(marker,p){const content=researchTooltip(p),hasTask=Boolean(content);marker.bindTooltip(content||`<strong>${escape(p.name||"Unnamed PokéStop")}</strong>`,{className:`research-hover${hasTask?"":" name-only"}`,direction:"top",offset:[0,-18]});return marker}
  function passesQuestFilter(p,type){if(state.mode==="planner"||type!=="POKESTOP")return true;const reports=state.reportsByStop.get(p.id)||[];return reports.length?reportsForStop(p.id).length>0:state.questFilter.showUnreported}
  function matchesMapSearch(p,type,query){if(!query)return true;if(String(p.name||"").toLocaleLowerCase("en").includes(query))return true;if(state.mode!=="research"||type!=="POKESTOP")return false;return reportsForStop(p.id).some(report=>rewardName(report.taskId,report.rewardId).toLocaleLowerCase("en").includes(query))}
  function rememberPois(pois){state.pois=pois;for(const poi of pois)state.knownPois.set(poi.id,poi)}
  function reportClusterIcon(count){return L.divIcon({className:"",html:`<div class="report-cluster"><strong>${count}</strong><span aria-hidden="true">🔍</span></div>`,iconSize:[52,52],iconAnchor:[26,26]})}
  function renderReportClusters(entries){const groups=[],zoom=map.getZoom(),mergeDistance=150;for(const entry of entries){const point=map.project([entry.p.latitude,entry.p.longitude],zoom),group=groups.find(candidate=>candidate.center.distanceTo(point)<=mergeDistance);if(group){const previous=group.entries.length;group.entries.push(entry);group.center=L.point((group.center.x*previous+point.x)/(previous+1),(group.center.y*previous+point.y)/(previous+1))}else groups.push({center:point,entries:[entry]})}let changed=true;while(changed){changed=false;outer:for(let left=0;left<groups.length;left++)for(let right=left+1;right<groups.length;right++)if(groups[left].center.distanceTo(groups[right].center)<=mergeDistance){const a=groups[left],b=groups[right],total=a.entries.length+b.entries.length;a.center=L.point((a.center.x*a.entries.length+b.center.x*b.entries.length)/total,(a.center.y*a.entries.length+b.center.y*b.entries.length)/total);a.entries.push(...b.entries);groups.splice(right,1);changed=true;break outer}}for(const cluster of groups){const group=cluster.entries,count=group.length;if(count===1){const entry=group[0],marker=addResearchTooltip(L.marker([entry.p.latitude,entry.p.longitude],{icon:icon(entry.t,entry.reward)}),entry.p);marker.on("click",()=>openPoi(entry.p)).addTo(poiLayer);continue}const center=map.unproject(cluster.center,zoom),marker=L.marker(center,{icon:reportClusterIcon(count),title:`${count} reported research locations`});marker.on("click",()=>map.fitBounds(L.latLngBounds(group.map(entry=>[entry.p.latitude,entry.p.longitude])),{padding:[45,45],maxZoom:15})).addTo(poiLayer)}}
  function renderPois(){poiLayer.clearLayers();const q=$("#search").value.trim().toLocaleLowerCase("en"),enabled=new Set($$("[data-filter]:checked").map(x=>x.dataset.filter)),zoomedOut=map.getZoom()<15,dotRadius=stopDotRadius(),source=state.mode==="research"&&zoomedOut?[...state.knownPois.values()]:state.pois,entries=[];for(const p of source){const t=typeOf(p),hasDetailedReport=reportsForStop(p.id).some(report=>!isRegularReport(report));if(state.mode==="research"&&zoomedOut&&!hasDetailedReport||!withinGeofence(Number(p.latitude),Number(p.longitude))||t==="GYM"&&state.mode!=="planner"||!enabled.has(t)||!passesQuestFilter(p,t)||!matchesMapSearch(p,t,q))continue;const rewardQuery=state.mode==="research"&&q&&!String(p.name||"").toLocaleLowerCase("en").includes(q)?q:"";entries.push({p,t,reward:state.mode==="research"?rewardForStop(p.id,rewardQuery,zoomedOut):null})}if(state.mode==="research"&&map.getZoom()<14)renderReportClusters(entries);else for(const {p,t,reward} of entries){let marker=reward?L.marker([p.latitude,p.longitude],{icon:icon(t,reward)}):L.circleMarker([p.latitude,p.longitude],{renderer:cellRenderer,radius:t==="GYM"?dotRadius+2:dotRadius,color:"#eafcff",weight:2,fillColor:t==="GYM"?"#e84b57":"#168ee3",fillOpacity:1});if(state.mode==="research"&&t==="POKESTOP")marker=addResearchTooltip(marker,p);marker.on("click",()=>openPoi(p)).addTo(poiLayer)}renderRadii();renderInteractionRanges()}
  function renderRadii(){radiusLayer.clearLayers();if(state.mode!=="planner"||map.getZoom()<15||!$("#radius20").checked)return;const q=$("#search").value.trim().toLowerCase(),enabled=new Set($$("[data-filter]:checked").map(x=>x.dataset.filter));for(const p of state.pois){const type=typeOf(p);if(!withinGeofence(Number(p.latitude),Number(p.longitude))||!enabled.has(type)||!passesQuestFilter(p,type)||q&&!p.name.toLowerCase().includes(q))continue;L.circle([p.latitude,p.longitude],{renderer:cellRenderer,radius:20,color:"#52e0a4",weight:1,opacity:.9,fillColor:"#52e0a4",fillOpacity:.12,interactive:false}).addTo(radiusLayer)}}
  function renderInteractionRanges(){interactionLayer.clearLayers();if(state.mode!=="planner"||map.getZoom()<15)return;const ranges=[];if($("#stopRange80").checked)ranges.push({type:"POKESTOP",radius:80,color:"#c06cff",fillOpacity:.14,lineOpacity:.95,weight:2.25});if($("#stopRange40").checked)ranges.push({type:"POKESTOP",radius:40,color:"#35d5ff",fillOpacity:.09,lineOpacity:.9,weight:2});if($("#gymRange80").checked)ranges.push({type:"GYM",radius:80,color:"#ff7a8a",fillOpacity:.075,lineOpacity:.9,weight:2});if(!ranges.length)return;if($("#rangeHotspots").checked){renderRangeHotspots();return}for(const p of state.pois){const type=typeOf(p);if(!withinGeofence(Number(p.latitude),Number(p.longitude)))continue;for(const range of ranges)if(type===range.type)L.circle([p.latitude,p.longitude],{renderer:interactionRenderer,radius:range.radius,color:range.color,weight:range.weight,opacity:range.lineOpacity,fillColor:range.color,fillOpacity:range.fillOpacity,interactive:false}).addTo(interactionLayer)}}
  function renderRangeHotspots(){const stopRadius=$("#stopRange80").checked?80:$("#stopRange40").checked?40:0,gymRadius=$("#gymRange80").checked?80:0;if(!stopRadius&&!gymRadius)return;const center=map.getCenter(),centerPoint=map.latLngToContainerPoint(center),metersToPixels=map.latLngToContainerPoint([center.lat+80/111320,center.lng]).distanceTo(centerPoint)/80,pois=[];for(const p of state.pois){const type=typeOf(p),radius=type==="POKESTOP"?stopRadius:type==="GYM"?gymRadius:0;if(radius&&withinGeofence(Number(p.latitude),Number(p.longitude)))pois.push({point:map.latLngToContainerPoint([p.latitude,p.longitude]),radiusSquared:(radius*metersToPixels)**2})}if(pois.length<2)return;const size=map.getSize(),step=24,samples=[];let maximum=0;for(let y=step/2;y<size.y;y+=step)for(let x=step/2;x<size.x;x+=step){let count=0;for(const poi of pois){const dx=x-poi.point.x,dy=y-poi.point.y;if(dx*dx+dy*dy<=poi.radiusSquared)count++}if(count>=2){maximum=Math.max(maximum,count);samples.push({point:L.point(x,y),count})}}if(maximum<2)return;for(const sample of samples){const strength=maximum===2?1:(sample.count-2)/(maximum-2),hue=38+18*strength,lightness=38+36*strength,northWest=map.containerPointToLatLng([sample.point.x-step/2,sample.point.y-step/2]),southEast=map.containerPointToLatLng([sample.point.x+step/2,sample.point.y+step/2]);L.rectangle(L.latLngBounds(northWest,southEast),{renderer:interactionRenderer,stroke:false,fillColor:`hsl(${hue} 100% ${lightness}%)`,fillOpacity:.22+.5*strength,interactive:false}).addTo(interactionLayer)}}
  async function toggleCompletedFromSheet(p,report){const wasCompleted=isResearchCompleted(p.id,report.taskId,report.rewardId);if(!wasCompleted&&!report.confirmedByYou)try{await reportApi("/api/research/report",{method:"POST",body:JSON.stringify({pokestopId:p.id,taskId:report.taskId,rewardId:report.rewardId,latitude:p.latitude,longitude:p.longitude,reporterId:REPORTER_ID,turnstileToken:null})});playReportFireworks(Number(p.latitude),Number(p.longitude));toast("Thank you for the report!");state.selectedReports=await reportApi(`/api/research?pokestopId=${encodeURIComponent(p.id)}&reporterId=${encodeURIComponent(REPORTER_ID)}`)}catch(error){toast(error.message);return}toggleResearchCompleted(p.id,report.taskId,report.rewardId);closeSheet();state.selected=null;state.selectedReports=[];renderPois();if(!wasCompleted)loadStatic()}
