  $$("[data-filter],#l17,#l14,#radius20,#stopRange40,#stopRange80,#gymRange80,#rangeHotspots").forEach(x=>x.addEventListener("change",()=>{renderPois();loadCells()}));$("#search").addEventListener("input",renderPois);$("#sheetBackdrop").addEventListener("click",closeSheet);$("#taskSelect").addEventListener("change",()=>{$("#rewardSearch").value="";fillRewards()});$("#taskSearch").addEventListener("input",fillTasks);$("#rewardSearch").addEventListener("input",()=>{renderRewardOptions();$("#rewardPickerMenu").classList.remove("hidden");$("#rewardPickerButton").setAttribute("aria-expanded","true")});$$('.field-search-toggle').forEach(button=>button.addEventListener("click",()=>{const input=$(button.dataset.searchTarget),visible=input.classList.contains("hidden");setPickerSearchVisible(input,visible);if(!visible){input.value="";if(input.id==="taskSearch")fillTasks();else renderRewardOptions()}}));$("#reportDialog").addEventListener("close",resetPickerSearches);$("#refresh").addEventListener("click",()=>{loadVisible();loadStatic()});
  $("#rewardPickerButton").addEventListener("click",()=>{const menu=$("#rewardPickerMenu"),open=menu.classList.contains("hidden");menu.classList.toggle("hidden",!open);$("#rewardPickerButton").setAttribute("aria-expanded",String(open))});document.addEventListener("click",event=>{if(!event.target.closest("#rewardPicker")){$("#rewardPickerMenu").classList.add("hidden");$("#rewardPickerButton").setAttribute("aria-expanded","false")}});
