  $("#locate").addEventListener("click",()=>map.locate({setView:false,enableHighAccuracy:true}));map.on("locationfound",event=>{showUserLocation(event);const supported=withinGeofence(event.latitude,event.longitude);document.body.classList.toggle("location-unsupported",!supported);$("#locationWarning").classList.toggle("hidden",supported);if(supported)map.setView(event.latlng,Math.max(map.getZoom(),17))});map.on("locationerror",()=>toast("Location unavailable"));
